-- ============================================================================
-- GeoClass - Dump de Dados para Supabase (PostgreSQL)
-- Gerado com IDs inteiros autoincrementais e Chaves Estrangeiras numéricas
-- OBS: Dias cancelados por feriados/emendas NÃO possuem registros em Attendance
-- ============================================================================

BEGIN;

SET CONSTRAINTS ALL DEFERRED;

-- 1. Room

-- 2. AcademicCalendar

-- 3. AcademicSemester

-- 4. User

-- 5. UserCourse

-- 6. Class

-- 7. TemporaryClassLocation

-- 8. Enrollment

-- 9. Attendance (Feriados/emendas não possuem registros de presença)

-- 10. Notification

-- 11. ClassCancellation

-- ============================================================================
-- Sincronização das Sequences (Autoincrement) do PostgreSQL
-- ============================================================================
SELECT setval(pg_get_serial_sequence('"User"', 'id'), coalesce((SELECT max(id) FROM "User"), 1));
SELECT setval(pg_get_serial_sequence('"Room"', 'id'), coalesce((SELECT max(id) FROM "Room"), 1));
SELECT setval(pg_get_serial_sequence('"AcademicCalendar"', 'id'), coalesce((SELECT max(id) FROM "AcademicCalendar"), 1));
SELECT setval(pg_get_serial_sequence('"AcademicSemester"', 'id'), coalesce((SELECT max(id) FROM "AcademicSemester"), 1));
SELECT setval(pg_get_serial_sequence('"Class"', 'id'), coalesce((SELECT max(id) FROM "Class"), 1));
SELECT setval(pg_get_serial_sequence('"UserCourse"', 'id'), coalesce((SELECT max(id) FROM "UserCourse"), 1));
SELECT setval(pg_get_serial_sequence('"TemporaryClassLocation"', 'id'), coalesce((SELECT max(id) FROM "TemporaryClassLocation"), 1));
SELECT setval(pg_get_serial_sequence('"Enrollment"', 'id'), coalesce((SELECT max(id) FROM "Enrollment"), 1));
SELECT setval(pg_get_serial_sequence('"Attendance"', 'id'), coalesce((SELECT max(id) FROM "Attendance"), 1));
SELECT setval(pg_get_serial_sequence('"Notification"', 'id'), coalesce((SELECT max(id) FROM "Notification"), 1));
SELECT setval(pg_get_serial_sequence('"ClassCancellation"', 'id'), coalesce((SELECT max(id) FROM "ClassCancellation"), 1));

COMMIT;
